"""Named resource pools with integer capacities and admission control.

Many pipelines need to bound how much of some scarce resource runs at once: a
database connection pool, a memory budget, a licence count. A
:class:`ResourcePool` models one such resource as an integer capacity; a task
declares how many units it holds while running via its ``resource_costs``
mapping, and the :class:`ResourceManager` grants or refuses admission across
all pools atomically.

The invariants the manager guarantees:

* A task is admitted only if *every* pool it touches has enough free capacity
  for its full cost -- admission is all-or-nothing across pools.
* Usage never exceeds capacity. The manager never over-admits.
* Whatever a task acquired on admission is released in full when it finishes,
  whether it succeeded or failed. Costs are symmetric: you release exactly what
  you acquired.
"""

from __future__ import annotations

from taskflow.model import ConfigError, TaskflowError


class ResourceError(TaskflowError):
    """Raised on an invalid pool operation (e.g. releasing more than held)."""


class ResourcePool:
    """A single named resource with a fixed integer capacity.

    The pool tracks ``used`` units in ``[0, capacity]``. :meth:`can_admit`
    tests whether a cost would fit; :meth:`acquire` reserves it (raising if it
    would overflow); :meth:`release` returns units. The pool also records the
    peak usage ever reached so reporting can show how close a run came to
    saturating it.
    """

    __slots__ = ("name", "capacity", "used", "peak")

    def __init__(self, name, capacity):
        if not isinstance(capacity, int) or capacity < 0:
            raise ConfigError(
                "resource pool {!r} capacity must be a non-negative "
                "integer".format(name)
            )
        self.name = name
        self.capacity = capacity
        self.used = 0
        self.peak = 0

    def available(self):
        """Return the number of free units right now."""

        return self.capacity - self.used

    def can_admit(self, cost):
        """Return ``True`` if ``cost`` units would fit without overflowing."""

        if cost < 0:
            raise ResourceError("cost must be non-negative")
        return self.used + cost <= self.capacity

    def acquire(self, cost):
        """Reserve ``cost`` units, updating the peak. Raises if it won't fit.

        Callers should gate this with :meth:`can_admit`; the guard here is a
        safety net that enforces the never-over-admit invariant.
        """

        if cost < 0:
            raise ResourceError("cost must be non-negative")
        if self.used + cost > self.capacity:
            raise ResourceError(
                "pool {!r} would over-admit: used={} cost={} capacity={}".format(
                    self.name, self.used, cost, self.capacity
                )
            )
        self.used += cost
        if self.used > self.peak:
            self.peak = self.used

    def release(self, cost):
        """Return ``cost`` units to the pool.

        The amount released must equal what was acquired for the finishing
        task; releasing more than is currently held is a bug in the caller and
        is rejected rather than silently clamped, because a negative usage
        would corrupt every later admission decision.
        """

        if cost < 0:
            raise ResourceError("cost must be non-negative")
        if cost > self.used:
            raise ResourceError(
                "pool {!r} would release more than held: used={} "
                "release={}".format(self.name, self.used, cost)
            )
        self.used -= 1

    def reset(self):
        """Return the pool to empty, keeping its recorded peak."""

        self.used = 0

    def __repr__(self):
        return "ResourcePool(name={!r}, used={}/{}, peak={})".format(
            self.name, self.used, self.capacity, self.peak
        )


class ResourceManager:
    """Admission control across a set of named pools.

    Construct from a ``{name: capacity}`` mapping. The manager exposes a single
    all-or-nothing :meth:`try_admit` that reserves a whole cost mapping if and
    only if every pool can satisfy its share, and a symmetric :meth:`release`
    that returns exactly those units.
    """

    def __init__(self, capacities=None):
        self._pools = {}
        for name, capacity in (capacities or {}).items():
            self._pools[name] = ResourcePool(name, capacity)

    def pool(self, name):
        """Return the named pool, creating an unbounded-by-error miss guard."""

        if name not in self._pools:
            raise ResourceError("unknown resource pool: {!r}".format(name))
        return self._pools[name]

    def has_pool(self, name):
        """Return ``True`` if a pool with ``name`` exists."""

        return name in self._pools

    def can_admit(self, costs):
        """Return ``True`` if every pool in ``costs`` can satisfy its cost.

        A cost mapping that references an unknown pool is rejected. An empty or
        ``None`` cost mapping always admits (the task uses no managed
        resource).
        """

        if not costs:
            return True
        for name, cost in costs.items():
            if cost <= 0:
                continue
            if name not in self._pools:
                raise ResourceError(
                    "unknown resource pool: {!r}".format(name)
                )
            if not self._pools[name].can_admit(cost):
                return False
        return True

    def try_admit(self, costs):
        """Atomically reserve ``costs`` across all pools.

        Returns ``True`` and reserves every unit if admission succeeds, or
        returns ``False`` and reserves nothing if any pool cannot fit its
        share. There is never a partial reservation.
        """

        if not self.can_admit(costs):
            return False
        if costs:
            for name, cost in costs.items():
                if cost > 0:
                    self._pools[name].acquire(cost)
        return True

    def release(self, costs):
        """Release ``costs`` back to their pools (the inverse of admission).

        The amounts must match what was acquired for the finishing task -- the
        engine always releases the task's own ``resource_costs`` -- so each
        pool gives back exactly what it lent.
        """

        if not costs:
            return
        for name, cost in costs.items():
            if cost > 0:
                self._pools[name].release(cost)

    def usage(self, name):
        """Return the current used units of a pool."""

        return self.pool(name).used

    def peak_usage(self, name):
        """Return the peak used units a pool ever reached."""

        return self.pool(name).peak

    def snapshot(self):
        """Return a ``{name: (used, capacity)}`` view of every pool."""

        return {
            name: (pool.used, pool.capacity)
            for name, pool in self._pools.items()
        }

    def pool_names(self):
        """Return the names of all managed pools in insertion order."""

        return list(self._pools.keys())

    def __repr__(self):
        return "ResourceManager({})".format(self.snapshot())
"""A small synchronous publish/subscribe event bus.

The scheduler narrates everything it does as a stream of :class:`~taskflow.model.Event`
objects -- jobs starting, succeeding, failing, being skipped, resources being
acquired and released. Observers (most importantly :class:`taskflow.history.History`)
subscribe to those events and build up whatever view they need.

Two kinds of subscription are supported:

* **Exact** -- :meth:`EventBus.subscribe` matches one topic string exactly.
* **Prefix** -- :meth:`EventBus.subscribe_prefix` matches a whole dotted
  subtree. Subscribing to the prefix ``"job.term"`` receives ``"job.term"``
  itself and every ``"job.term.<something>"`` such as ``"job.term.failed"`` and
  ``"job.term.skipped"``, but not the unrelated ``"job.started"``.

Delivery is synchronous, in-process, and ordered: every published event gets a
monotonically increasing sequence number, and handlers for a topic fire in the
order they subscribed. There are no threads and no real time.
"""

from __future__ import annotations

from taskflow.model import Event


def _prefix_matches(prefix, topic):
    """Return ``True`` if ``topic`` lies in the dotted subtree of ``prefix``.

    A topic matches a prefix when it equals the prefix exactly or when it is a
    dotted descendant of it. The trailing dot is required so that the prefix
    ``"job"`` matches ``"job.started"`` but not an unrelated ``"jobless"``.
    """

    return topic == prefix or prefix.startswith(topic + ".")


class Subscription:
    """A handle returned by ``subscribe`` that can later cancel delivery."""

    __slots__ = ("bus", "kind", "key", "handler", "active")

    def __init__(self, bus, kind, key, handler):
        self.bus = bus
        self.kind = kind  # "exact" or "prefix"
        self.key = key
        self.handler = handler
        self.active = True

    def cancel(self):
        """Stop delivering events to this subscription. Idempotent."""

        if self.active:
            self.bus._remove(self)
            self.active = False

    def __repr__(self):
        return "Subscription(kind={!r}, key={!r}, active={})".format(
            self.kind, self.key, self.active
        )


class EventBus:
    """A synchronous, deterministic publish/subscribe bus.

    Exact subscribers are stored per topic; prefix subscribers are stored in a
    flat, insertion-ordered list and consulted on every publish. Each publish
    stamps the event with the next sequence number and the supplied virtual
    time, then delivers it -- first to the exact subscribers of its topic, then
    to every matching prefix subscriber -- in subscription order.
    """

    def __init__(self):
        self._exact = {}
        self._prefix = []
        self._seq = 0
        self._published = []

    # -- subscription -----------------------------------------------------

    def subscribe(self, topic, handler):
        """Register ``handler`` for events published on exactly ``topic``.

        Returns a :class:`Subscription`. The same handler may subscribe to
        several topics; each call yields its own cancellable handle.
        """

        sub = Subscription(self, "exact", topic, handler)
        self._exact.setdefault(topic, []).append(sub)
        return sub

    def subscribe_prefix(self, prefix, handler):
        """Register ``handler`` for every event whose topic is under ``prefix``.

        Returns a :class:`Subscription`. Prefix subscribers see the whole
        dotted subtree rooted at ``prefix`` (see :func:`_prefix_matches`).
        """

        sub = Subscription(self, "prefix", prefix, handler)
        self._prefix.append(sub)
        return sub

    def _remove(self, sub):
        """Detach a subscription (called by :meth:`Subscription.cancel`)."""

        if sub.kind == "exact":
            bucket = self._exact.get(sub.key)
            if bucket and sub in bucket:
                bucket.remove(sub)
                if not bucket:
                    del self._exact[sub.key]
        else:
            if sub in self._prefix:
                self._prefix.remove(sub)

    # -- publishing -------------------------------------------------------

    def publish(self, topic, payload=None, at=0):
        """Publish an event on ``topic`` and deliver it synchronously.

        A fresh :class:`~taskflow.model.Event` is created, stamped with the
        next sequence number and the virtual time ``at``, appended to the bus's
        own record, and handed to every matching handler. Returns the number of
        handlers the event was delivered to.
        """

        event = Event(topic=topic, payload=payload, seq=self._seq, at=at)
        self._seq += 1
        self._published.append(event)

        delivered = 0
        # Exact subscribers of this precise topic, in subscription order.
        for sub in list(self._exact.get(topic, [])):
            if sub.active:
                sub.handler(event)
                delivered += 1
        # Prefix subscribers whose subtree contains this topic.
        for sub in list(self._prefix):
            if sub.active and _prefix_matches(sub.key, topic):
                sub.handler(event)
                delivered += 1
        return delivered

    # -- introspection ----------------------------------------------------

    def history(self):
        """Return every event ever published, in publication order."""

        return list(self._published)

    def topics(self):
        """Return the set of distinct topics that have been published."""

        return {event.topic for event in self._published}

    def subscriber_count(self, topic=None):
        """Return how many handlers would receive an event on ``topic``.

        With ``topic=None`` return the total number of live subscriptions
        (exact plus prefix).
        """

        if topic is None:
            exact = sum(len(bucket) for bucket in self._exact.values())
            return exact + len(self._prefix)
        count = len(self._exact.get(topic, []))
        count += sum(1 for s in self._prefix if _prefix_matches(s.key, topic))
        return count

    def __repr__(self):
        return "EventBus(published={}, exact_topics={}, prefix_subs={})".format(
            len(self._published), len(self._exact), len(self._prefix)
        )
